effect.shader:
const float PI = 3.14159265;

vec2 dir(float graus) {
    float a = graus * PI / 180.0;
    return vec2(cos(a), sin(a));
}

vec3 amostraCanal(vec2 origem, vec2 direcao, float raio, int canal, int n) {
    float soma = 0.0;
    float peso = 0.0;
    for (int i = 0; i <= 48; i++) {
        if (i > n) break;
        float t = float(i) / float(n);
        vec2 p = origem + direcao * raio * t;
        float v = texture(inputImg, p)[canal];
        soma += v;
        peso += 1.0;
    }
    return vec3(soma / max(peso, 1e-4));
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);
    if (amount <= 0.0) { fragColor = original; return; }

    int n = clamp(int(samples), 4, 48);

    // Três pares opostos: R/G/B cada um pega um eixo do leque.
    vec2 dR1 = dir(angle - spread);
    vec2 dR2 = dir(angle - spread + 180.0);
    vec2 dG1 = dir(angle);
    vec2 dG2 = dir(angle + 180.0);
    vec2 dB1 = dir(angle + spread);
    vec2 dB2 = dir(angle + spread + 180.0);

    float r = (amostraCanal(acScreenNorm, dR1, amount, 0, n).r
             + amostraCanal(acScreenNorm, dR2, amount, 0, n).r) * 0.5;
    float g = (amostraCanal(acScreenNorm, dG1, amount, 1, n).r
             + amostraCanal(acScreenNorm, dG2, amount, 1, n).r) * 0.5;
    float b = (amostraCanal(acScreenNorm, dB1, amount, 2, n).r
             + amostraCanal(acScreenNorm, dB2, amount, 2, n).r) * 0.5;

    vec3 cor = vec3(r, g, b) * boost;
    fragColor = vec4(cor, original.a);
}
